 by('cgBlockWhat').textContent=`从${time(d.arrival)}到${time(d.end)}，这一关前后共${time(d.seconds)}没有新关。${d.failures?'这关实际失败'+d.failures+'场。':'没有失败记录。'}`;let reason=diagnoseText(d)+'。';const w=d.loginWitness;if(w&&w.affordableAt!==null){reason+=`从下线记录的${f(w.balanceBefore)}金币开始，还差${f(w.resourceGap)}；这笔升级在游戏开始${time(w.affordableAt)}时已买得起，但到${time(w.end)}才上线。攒钱时间和等上线时间不是同一件事。`;}else if(d.cause==='waiting_for_login')reason+='下线期间只收固定金币，没有购买或新挑战。';else if(d.actualBattle){reason+=`当时角色剩${f(d.actualBattle.playerHp)}血，敌人剩${f(d.actualBattle.enemyHp)}血；战斗用时${time(d.actualBattle.seconds)}。`;}
